class Solution:
    def canPartition(self, nums: List[int]) -> bool:
        total = sum(nums)
        if total % 2:
            return False
        target = total // 2
        dp = [True] + [False] * target      # dp[j]：能不能凑出和 j
        for x in nums:
            for j in range(target, x - 1, -1):  # 倒序：每个数只用一次
                dp[j] = dp[j] or dp[j - x]
        return dp[target]

class Solution:
    def canPartition(self, nums: List[int]) -> bool:
        total, bits = sum(nums), 1
        for x in nums:
            bits |= bits << x
        return total % 2 == 0 and (bits >> (total // 2)) & 1 == 1

