        const nb = bits.slice(), fresh = [];
        for (let j = total; j >= x; j--) if (bits[j - x] && !bits[j]) { nb[j] = 1; fresh.push(j); }
        bits = nb;
        snap(`加入 ${x}`, `bits << ${x}：每个能凑出的和都加上 ${x}，再和原来的 bits 按位或。` + (fresh.length ? `新能凑出 ${fresh.slice().reverse().join("、")}。` : "没有新的和。"), view(k, fresh), f());
      });
